def compare(context):
 from django.db import connection,transaction
 source=context['EPGSource'];index=context['EPGSourceIndex'];sid=context['sid'];label=context['label'];original=context['report']['cases'][-1];cache=context['cache'];broker=context['broker'];backend=context['backend'];app=context['app'];check=context['check'];table='rust_native_race_'+str(sid)
 if not source.objects.filter(pk=sid).exists():source.objects.bulk_create([source(id=sid,name=context['source'].name,source_type='xmltv',is_active=True,file_path=str(context['path']))])
