  check('native-race-actual-Source-AsyncResult-'+label,app.AsyncResult(issued.id).get(timeout=2)is None and meta['status']=='SUCCESS'and meta['result']is None and meta['traceback']is None and meta['children']==[])
  check('native-race-exact-row-effects-'+label,canonical(state)==canonical(original['source_state'])and(any(row==('source_update',0)for row in writes)if label.startswith('delete_')else any(row==('source_update',1)for row in writes)))
  check('native-race-actual-publication-call-'+label,canonical(publications)==canonical(original['progress_messages']))
